use std::{io::{self,BufRead},collections::BTreeMap,sync::Arc,panic::{catch_unwind,AssertUnwindSafe}};
use serde_json::{json,Value as J};
use teaql_runtime::{EntityValues,GraphNode,GraphOperation,GraphMutationKind,GraphMutationPlan,TraceScopeToken};
use teaql_core::{Value,TraceNode,TraceKind,MutationValues,EntitySnapshot};
fn value(j:&J)->Value{match j["kind"].as_str().unwrap(){"null"=>Value::Null,"text"=>Value::Text(j["value"].as_str().unwrap().into()),"i64"=>Value::I64(j["value"].as_str().unwrap().parse().unwrap()),"u64"=>Value::U64(j["value"].as_str().unwrap().parse().unwrap()),"bool"=>Value::Bool(j["value"].as_bool().unwrap()),"list"=>Value::List(j["value"].as_array().unwrap().iter().map(value).collect()),"object"=>Value::Object(record(&j["value"])),_=>panic!("fixture value")}}
fn record(j:&J)->BTreeMap<String,Value>{j.as_object().unwrap().iter().map(|(k,v)|(k.clone(),value(v))).collect()}
fn record_out(r:&BTreeMap<String,Value>)->J{json!(r.iter().map(|(k,v)|(k.clone(),format!("{v:?}"))).collect::<BTreeMap<_,_>>())}
fn strings(j:&J)->Vec<String>{j.as_array().unwrap().iter().map(|s|s.as_str().unwrap().into()).collect()}
fn node(j:&J)->GraphNode{let mut n=GraphNode::new(j["entity"].as_str().unwrap()).operation([GraphOperation::Upsert,GraphOperation::Create,GraphOperation::Reference,GraphOperation::Remove][j["operation"].as_u64().unwrap() as usize]);for (k,v) in record(&j["values"]){n=n.value(k,v);}if let Some(s)=j["comment"].as_str(){n.set_comment(s);}n.dirty_fields=j["dirty"].as_array().map(|_|strings(&j["dirty"]).into_iter().collect());n.original_values=if j["old"].is_null(){None}else{Some(record(&j["old"]).into())};for (name,children) in j["relations"].as_object().unwrap(){n=n.relations(name,children.as_array().unwrap().iter().map(node));}n}
fn node_out(n:&GraphNode)->J{json!({"entity":n.entity,"values":record_out(&n.values),"operation":format!("{:?}",n.operation),"comment":n.comment,"dirty":n.dirty_fields,"old":n.original_values.as_ref().map(|v|record_out(v)),"id":n.id().map(|v|format!("{v:?}")),"relations":n.relations.iter().map(|(k,v)|(k.clone(),v.iter().map(node_out).collect::<Vec<_>>())).collect::<BTreeMap<_,_>>()})}
fn trace_out(t:&Option<Arc<TraceScopeToken>>)->J{t.as_ref().map(|t|json!({"index":t.node_index.to_string(),"chain":t.recover_trace_chain().iter().map(|n|json!({"entity":n.entity_type,"comment":n.comment,"id":n.entity_id.map(|n|n.to_string())})).collect::<Vec<_>>()})).unwrap_or(J::Null)}
fn item_out(i:&teaql_runtime::GraphMutationPlanItem)->J{json!({"entity":i.entity,"kind":format!("{:?}",i.kind),"fields":i.update_fields,"index":i.item_index.to_string(),"values":record_out(&i.values),"old":i.old_values.as_ref().map(|v|record_out(v)),"scope":trace_out(&i.scope_token)})}
fn plan_out(p:&GraphMutationPlan)->J{json!({"items":p.items.iter().map(item_out).collect::<Vec<_>>(),"batches":p.batches.iter().map(|b|json!({"entity":b.entity,"kind":format!("{:?}",b.kind),"fields":b.update_fields,"items":b.items.iter().map(item_out).collect::<Vec<_>>()})).collect::<Vec<_>>(),"counts":p.grouped_counts().iter().map(|((e,k),n)|json!([e,format!("{k:?}"),n.to_string()])).collect::<Vec<_>>(),"next":p.next_item_index.to_string(),"len":p.len().to_string(),"batch_count":p.batch_count().to_string(),"empty":p.is_empty(),"root":p.planned_root.as_ref().map(node_out)})}
fn evaluate(j:J)->J{if j["mode"]=="node"{let n=node(&j["node"]);let copy=n.clone();let fields=teaql_runtime::sorted_update_fields(&copy.values,strings(&j["excluded"]));let command:MutationValues=copy.values.clone().into();let roundtrip:EntityValues=command.into();return json!({"node":node_out(&copy),"fields":fields,"roundtrip":roundtrip==copy.values});}
 let mut p=GraphMutationPlan::default();p.next_item_index=j["start"].as_str().unwrap().parse().unwrap();if !j["root"].is_null(){p.planned_root=Some(node(&j["root"]));}let mut trace=None;for (i,t) in j["trace"].as_array().unwrap().iter().enumerate(){trace=Some(Arc::new(TraceScopeToken{parent:trace,track:TraceNode::typed(TraceKind::Entity,t["entity"].as_str().unwrap(),Some(i as u64),t["comment"].as_str().unwrap()),node_index:i as u64}));}let mut out=vec![];
 for step in j["steps"].as_array().unwrap(){let mut overflow=false;match step["op"].as_str().unwrap(){"push"=>{let values:MutationValues=record(&step["values"]).into();let old:Option<EntitySnapshot>=if step["old"].is_null(){None}else{Some(record(&step["old"]).into())};let kind=[GraphMutationKind::Create,GraphMutationKind::Update,GraphMutationKind::Delete,GraphMutationKind::Reference][step["kind"].as_u64().unwrap() as usize];overflow=catch_unwind(AssertUnwindSafe(||p.push(step["entity"].as_str().unwrap(),kind,values,strings(&step["fields"]),if step["scope"]==true{trace.clone()}else{None},old))).is_err();},"rebuild"=>p.rebuild_batches(),"clear_items"=>p.items.clear(),"clear_batches"=>p.batches.clear(),_=>panic!("step")};out.push(json!({"plan":plan_out(&p.clone()),"overflow":overflow}));}json!(out)
}
fn main(){std::panic::set_hook(Box::new(|_|{}));for line in io::stdin().lock().lines(){println!("{}",evaluate(serde_json::from_str(&line.unwrap()).unwrap()));}}
